corrected_code:
const express = require('express');
const session = require('express-session');
const MongoStore = require('connect-mongo');

const app = express();

const mongoStore = MongoStore.create({
  mongoUrl: process.env.MONGO_URI,
  collectionName: 'app_sessions'
});

app.use(session({
  store: mongoStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.delete('/api/sessions/:sessionId/revoke', (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // First fetch the session to verify ownership
  mongoStore.get(req.params.sessionId, (err, targetSession) => {
    if (err || !targetSession) {
      return res.status(404).json({ error: 'Target session not found' });
    }

    // Ensure users can only destroy their own sessions
    if (targetSession.userId !== req.session.userId && req.session.role !== 'SECURITY_ADMIN') {
      return res.status(403).json({ error: 'Permission denied: cannot revoke another user\'s session' });
    }

    mongoStore.destroy(req.params.sessionId, (destroyErr) => {
      if (destroyErr) {
        return res.status(500).json({ error: 'Session revocation failed' });
      }
      res.json({ success: true, message: `Session ${req.params.sessionId} invalidated` });
    });
  });
});

app.listen(4000);
